sys_variable_value.value:
(function execute(inputs, outputs) {
    var tr = inputs.trigger_record;
    var appSysId = tr.sys_id.toString();
    var candSysId = tr.candidate.toString();
    var reqSysId = tr.requisition.toString();
    var candidateName = tr.candidate.full_name.toString();
    var roleTitle = tr.requisition.role_title.toString();

    // ── 1. Get screening result ──
    var screenGr = new GlideRecord('x_snc_aegis_screening_result');
    screenGr.addQuery('application', appSysId);
    screenGr.addQuery('screening_status', 'COMPLETED');
    screenGr.setLimit(1);
    screenGr.query();

    var fitScore = 0;
    var screeningExplanation = '';
    if (screenGr.next()) {
        fitScore = parseInt(screenGr.getValue('fit_score'), 10) || 0;
        screeningExplanation = screenGr.getValue('explanation') || '';
    }

    // ── 2. Get all interview syntheses ──
    var intGr = new GlideRecord('x_snc_aegis_interview');
    intGr.addQuery('application', appSysId);
    intGr.addQuery('synthesis_status', 'COMPLETED');
    intGr.query();

    var interviewSummaries = [];
    var overallConsensus = [];
    while (intGr.next()) {
        interviewSummaries.push({
            type: intGr.interview_type.getDisplayValue(),
            outcome: intGr.getValue('outcome'),
            synthesis: intGr.getValue('feedback_synthesis') || ''
        });
        overallConsensus.push(intGr.getValue('outcome'));
    }

    // ── 3. Determine AI recommendation ──
    var positiveCount = 0;
    var negativeCount = 0;
    for (var i = 0; i < overallConsensus.length; i++) {
        if (overallConsensus[i] === 'POSITIVE') positiveCount++;
        if (overallConsensus[i] === 'NEGATIVE') negativeCount++;
    }

    var aiRecommendation = 'HOLD';
    var confidence = 0.5;
    var reasoning = '';

    if (fitScore >= 70 && positiveCount > negativeCount && negativeCount === 0) {
        aiRecommendation = 'SELECT';
        confidence = Math.min(0.95, (fitScore / 100) * 0.6 + (positiveCount / Math.max(overallConsensus.length, 1)) * 0.4);
        reasoning = 'Strong candidate. Screening fit score of ' + fitScore + '/100 indicates solid skill alignment. ' +
            'All ' + positiveCount + ' interview round(s) returned positive consensus. ' +
            'No negative interview outcomes recorded. Recommend proceeding with offer.';
    } else if (negativeCount > positiveCount || fitScore < 40) {
        aiRecommendation = 'REJECT';
        confidence = Math.min(0.90, 0.5 + (negativeCount / Math.max(overallConsensus.length, 1)) * 0.4);
        reasoning = 'Candidate does not meet the bar. ';
        if (fitScore < 40) reasoning += 'Screening fit score of ' + fitScore + '/100 is below minimum threshold. ';
        if (negativeCount > 0) reasoning += negativeCount + ' interview round(s) returned negative consensus. ';
        reasoning += 'Recommend rejection with respectful candidate communication.';
    } else {
        confidence = 0.55;
        reasoning = 'Mixed signals. Screening fit score: ' + fitScore + '/100. ';
        reasoning += 'Interview outcomes: ' + positiveCount + ' positive, ' + negativeCount + ' negative, ' +
            (overallConsensus.length - positiveCount - negativeCount) + ' mixed. ';
        reasoning += 'Recommend human review — hiring manager should evaluate specific concerns before proceeding.';
    }

    // ── 4. Build synthesis summary ──
    var synthesisSummary = '=== HIRING DECISION EVIDENCE PACKAGE ===\n';
    synthesisSummary += 'Candidate: ' + candidateName + '\n';
    synthesisSummary += 'Role: ' + roleTitle + '\n\n';
    synthesisSummary += '--- SCREENING ---\n';
    synthesisSummary += 'Fit Score: ' + fitScore + '/100\n';
    synthesisSummary += screeningExplanation + '\n\n';
    synthesisSummary += '--- INTERVIEW ROUNDS ---\n';
    for (var j = 0; j < interviewSummaries.length; j++) {
        synthesisSummary += '[' + interviewSummaries[j].type + '] Outcome: ' + interviewSummaries[j].outcome + '\n';
    }
    synthesisSummary += '\n--- AI RECOMMENDATION ---\n';
    synthesisSummary += 'Decision: ' + aiRecommendation + ' (Confidence: ' + Math.round(confidence * 100) + '%)\n';
    synthesisSummary += reasoning;

    // ── 5. Create Hiring Decision record ──
    var hdGr = new GlideRecord('x_snc_aegis_hiring_decision');
    hdGr.initialize();
    hdGr.setValue('application', appSysId);
    hdGr.setValue('candidate', candSysId);
    hdGr.setValue('requisition', reqSysId);
    hdGr.setValue('ai_recommendation', aiRecommendation);
    hdGr.setValue('ai_confidence', confidence);
    hdGr.setValue('ai_reasoning', reasoning);
    hdGr.setValue('synthesis_summary', synthesisSummary);
    hdGr.setValue('decision_status', 'PENDING_HUMAN');
    hdGr.setValue('is_override', false);
    hdGr.setValue('closure_complete', false);

    var hdSysId = hdGr.insert();

    // ── 6. Log ──
    var logger = new x_snc_aegis.AEGISDecisionLogger();
    logger.logAction(
        'Hiring Decision Engine',
        'HIRING_RECOMMENDATION',
        appSysId,
        reqSysId,
        'Screening: ' + fitScore + '/100 | Interviews: ' +
            positiveCount + ' positive, ' + negativeCount + ' negative',
        'AI Recommendation: ' + aiRecommendation + ' | Confidence: ' +
            Math.round(confidence * 100) + '% | ' + reasoning.substring(0, 300),
        confidence,
        'Evidence-based recommendation; Human review required; Override audit enforced by BR-4'
    );

    outputs.hiring_decision_sys_id = hdSysId;
    outputs.ai_recommendation = aiRecommendation;

})(inputs, outputs);

